// Usage: node pipeline/check-weekly-cadence.mjs
// Detects whether this week's weekly recap package (video + WordPress
// weekly wrap + Substack weekly + Medium weekly) is due, based on the
// actual 7-day cadence already in use (Sept 7 -> Sept 14 -> Sept 21...).
// Built 2026-09-19 after the user flagged that Substack/Medium weekly
// generation had no automated check at all — WordPress's own weekly
// wrap and the weekly-recap video were being generated by memory/habit,
// with nothing catching a missed week the way check-missed-days.mjs and
// check-platform-coverage.mjs already catch gaps in the daily pillars.
//
// This is DETECTION-only, same contract as check-platform-coverage.mjs —
// it reports what's due or overdue, it doesn't generate anything itself.
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");

async function fileExists(p) {
  try {
    await fs.access(p);
    return true;
  } catch {
    return false;
  }
}

async function findLastWeeklyDate() {
  const wpDir = path.join(ROOT, "public", "wordpress");
  const files = await fs.readdir(wpDir);
  const weeklyDates = files
    .filter((f) => f.endsWith("-weekly.json"))
    .map((f) => f.replace("-weekly.json", ""))
    .sort();
  return weeklyDates.length ? weeklyDates[weeklyDates.length - 1] : null;
}

function addDays(dateStr, n) {
  const d = new Date(`${dateStr}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

function todayUtc() {
  return new Date().toISOString().slice(0, 10);
}

async function main() {
  const lastWeekly = await findLastWeeklyDate();
  if (!lastWeekly) {
    console.log("No weekly wrap found yet at all — nothing to base a cadence check on.");
    return;
  }

  const nextDue = addDays(lastWeekly, 7);
  const today = todayUtc();

  console.log(`Last weekly package: ${lastWeekly}. Next due: ${nextDue} (today: ${today}).`);

  if (today < nextDue) {
    console.log(`Not due yet — ${Math.ceil((new Date(nextDue) - new Date(today)) / 86400000)} day(s) remaining.`);
    return;
  }

  // Due (today >= nextDue) — check each piece of the weekly package
  // separately, since they're prepared by different scripts and can
  // drift out of sync with each other (WordPress weekly written but
  // Substack/Medium forgotten, etc).
  const checks = [
    { label: "WordPress weekly wrap", path: path.join(ROOT, "public", "wordpress", `${nextDue}-weekly.json`) },
    { label: "Substack weekly", path: path.join(ROOT, "public", "substack", `${nextDue}-weekly.md`) },
    { label: "Medium weekly", path: path.join(ROOT, "public", "medium", `${nextDue}-weekly.md`) },
  ];

  const missing = [];
  for (const c of checks) {
    if (!(await fileExists(c.path))) missing.push(c.label);
  }

  // Weekly recap VIDEO lives in content-queue, not public/ — checked
  // separately since it's a queue folder, not a single JSON/MD file.
  const videoDir = path.join(ROOT, "content-queue", "pending", `${nextDue}_weekly-recap`);
  if (!(await fileExists(videoDir))) missing.push("Weekly recap video");

  if (missing.length === 0) {
    console.log(`Weekly package for ${nextDue} is DUE and already complete — no action needed.`);
  } else {
    console.log(`\nWeekly package for ${nextDue} is DUE. Missing: ${missing.join(", ")}.`);
    console.log(`Run in order once the week's daily pillars are all in: render-weekly-recap.mjs -> write public/wordpress/${nextDue}-weekly.json -> wordpress-cover.mjs ${nextDue} --weekly -> wordpress-publish.mjs ${nextDue} --weekly -> substack-prepare.mjs ${nextDue} --weekly -> medium-prepare.mjs ${nextDue}.`);
    process.exitCode = 1;
  }
}

main().catch((err) => {
  console.error(err.message ?? err);
  process.exit(1);
});
